// READ-ONLY. Builds GET urls only. Called by the EN source audit MCP server.
const inp = $input.first().json || {};
const mode = String(inp.mode || '').trim();
const MODES = ['projects', 'languages', 'keys', 'glossary'];
if (MODES.indexOf(mode) === -1) { throw new Error('mode must be one of: ' + MODES.join(', ')); }
const GLOSSARY_PROJECT = '46552447679363c70f7ef8.58193285';
const BASE = 'https://api.lokalise.com/api2';
let pid = String(inp.project_id || '').trim();
if (mode === 'glossary' && !pid) { pid = GLOSSARY_PROJECT; }
if (mode === 'projects') {
  return [{ json: { mode: mode, project_id: '', url: BASE + '/projects?limit=500' } }];
}
if (!/^[0-9a-z]+[.][0-9]+$/.test(pid)) {
  throw new Error('project_id must be a Lokalise project id such as 691331356a3b9a68428ab3.43540470 (got: ' + pid + ')');
}
if (mode === 'languages') {
  return [{ json: { mode: mode, project_id: pid, url: BASE + '/projects/' + pid + '/languages?limit=500' } }];
}
if (mode === 'glossary') {
  return [{ json: { mode: mode, project_id: pid, url: BASE + '/projects/' + pid + '/glossary-terms?limit=500' } }];
}
// include_translations=1 is required: the EN source arrives inside the translations array.
// filter_translation_lang_ids=640 keeps only English. Archived keys are never audited.
let qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor&filter_translation_lang_ids=640&filter_archived=exclude';
const tags = String(inp.filter_tags || '').trim();
if (tags) { qs += '&filter_tags=' + encodeURIComponent(tags); }
return [{ json: { mode: mode, project_id: pid, url: BASE + '/projects/' + pid + '/keys?' + qs } }];

// One compact result for the MCP client. Archived keys skipped and counted.
const pages = $input.all();
const cfg = $('Validate and build URL').first().json;
const rows = [];
const errors = [];
let keysSeen = 0, sourceMissing = 0, archivedSkipped = 0, totalCount = null;
for (const p of pages) {
  const r = p.json || {};
  const body = (r.body !== undefined ? r.body : r) || {};
  const h = r.headers || {};
  if (h['x-pagination-total-count']) { totalCount = Number(h['x-pagination-total-count']); }
  if (cfg.mode === 'projects') {
    for (const pr of (body.projects || [])) {
      rows.push({ project_id: pr.project_id, name: pr.name, keys_total: (pr.statistics && pr.statistics.keys_total) || null, base_language: pr.base_language_iso || '' });
    }
    continue;
  }
  if (cfg.mode === 'languages') {
    for (const l of (body.languages || [])) { rows.push({ lang_id: l.lang_id, iso: l.lang_iso, name: l.lang_name }); }
    continue;
  }
  if (cfg.mode === 'glossary') {
    for (const t of (body.data || [])) {
      rows.push({ term: t.term, description: t.description || '', case_sensitive: !!t.caseSensitive, translatable: t.translatable !== false, forbidden: !!t.forbidden, tags: t.tags || [] });
    }
    continue;
  }
  if (!Array.isArray(body.keys)) {
    errors.push({ statusCode: r.statusCode, body: JSON.stringify(body).slice(0, 300) });
    continue;
  }
  for (const key of body.keys) {
    if (key.is_archived === true) { archivedSkipped++; continue; }
    keysSeen++;
    const tr = Array.isArray(key.translations) ? key.translations : [];
    const en = tr.find(function (t) { return t.language_iso === 'en'; });
    const name = typeof key.key_name === 'object' ? (key.key_name.web || key.key_name.other || '') : key.key_name;
    if (!en || en.translation === undefined || en.translation === null || en.translation === '') { sourceMissing++; continue; }
    rows.push({ key_id: key.key_id, k: name, en: en.translation, description: key.description || '', plural: !!key.is_plural, tags: key.tags || [], modified_by: en.modified_by_email || '' });
  }
}
const out = { mode: cfg.mode, project_id: cfg.project_id, pages: pages.length, rows_kept: rows.length, errors: errors };
if (cfg.mode === 'keys') {
  out.keys_seen = keysSeen; out.source_missing = sourceMissing; out.archived_skipped = archivedSkipped;
  out.note = 'Compare keys_seen with keys_total from list_lokalise_projects before trusting the result.';
}
if (totalCount !== null) { out.server_total = totalCount; }
out.rows = rows;
return [{ json: out }];
